57	inline UInt16 GetUi16(const Byte *p) { UInt16 v; memcpy(&v, p, 2); return v; }
58	inline UInt32 GetUi32(const Byte *p) { UInt32 v; memcpy(&v, p, 4); return v; }
59	inline UInt64 GetUi64(const Byte *p) { UInt64 v; memcpy(&v, p, 8); return v; }
60	inline void SetUi16(Byte *p, UInt16 v) { memcpy(p, &v, 2); }
61	inline void SetUi32(Byte *p, UInt32 v) { memcpy(p, &v, 4); }
62	inline void SetUi64(Byte *p, UInt64 v) { memcpy(p, &v, 8); }
