7	// Progress reporting hook. Codecs call it so the UI can print percentages.
8	struct IProgress {
9	  virtual ~IProgress() {}
10	  // inSize/outSize are cumulative for the current operation; either may be
11	  // (UInt64)-1 when unknown.
12	  virtual void SetRatioInfo(UInt64 inSize, UInt64 outSize) = 0;
13	};
