15	struct ISeqInStream {
16	  virtual ~ISeqInStream() {}
17	  // Reads up to len bytes.  Returns the number read; a short read (including
18	  // 0) means end of stream.
19	  virtual size_t Read(Byte *buf, size_t len) = 0;
20	  // Reads exactly len bytes or throws ERR_UNEXPECTED_END.
21	  void ReadFull(Byte *buf, size_t len);
22	  // Reads exactly len bytes, returns false on immediate EOF.
23	  bool ReadFullOrEof(Byte *buf, size_t len);
24	  Byte ReadByte() { Byte b; ReadFull(&b, 1); return b; }
25	  void Skip(UInt64 len);
26	};
27	
28	struct ISeqOutStream {
29	  virtual ~ISeqOutStream() {}
30	  virtual void Write(const Byte *buf, size_t len) = 0;
31	  void WriteByte(Byte b) { Write(&b, 1); }
32	};
33	
34	// ------------------------------------------------------------- memory streams
35	
36	struct MemInStream : ISeqInStream {
37	  const Byte *p; size_t size, pos;
38	  MemInStream(const Byte *d, size_t n) : p(d), size(n), pos(0) {}
39	  MemInStream(const ByteBuf &b) : p(b.empty() ? nullptr : &b[0]), size(b.size()), pos(0) {}
40	  size_t Read(Byte *buf, size_t len) override {
41	    size_t n = size - pos;
42	    if (n > len) n = len;
43	    if (n) memcpy(buf, p + pos, n);
44	    pos += n;
45	    return n;
46	  }
47	};
48	
49	struct MemOutStream : ISeqOutStream {
50	  ByteBuf buf;
51	  void Write(const Byte *b, size_t len) override { buf.insert(buf.end(), b, b + len); }
52	};
53	
54	// Discards everything, counting the size.
55	struct NullOutStream : ISeqOutStream {
56	  UInt64 total = 0;
57	  void Write(const Byte *, size_t len) override { total += len; }
58	};
59	
60	// ------------------------------------------------------------- file streams
