62	struct FileInStream : ISeqInStream {
63	  FILE *f = nullptr;
64	  bool owned = false;
65	  UInt64 pos = 0;
66	  ~FileInStream() { Close(); }
67	  bool Open(const std::string &path);
68	  void AttachStdin();
69	  void Close();
70	  size_t Read(Byte *buf, size_t len) override;
