77	  bool owned = false;
78	  UInt64 pos = 0;
79	  ~FileOutStream() { Close(); }
80	  bool Create(const std::string &path);
81	  void AttachStdout();
82	  void Close();
83	  void Write(const Byte *buf, size_t len) override;
84	};
