86	// ------------------------------------------------------------ wrapper streams
87	
88	// Limits how much can be read from the underlying stream.
89	struct LimitedInStream : ISeqInStream {
90	  ISeqInStream *base; UInt64 rem;
91	  LimitedInStream(ISeqInStream *b, UInt64 n) : base(b), rem(n) {}
92	  size_t Read(Byte *buf, size_t len) override {
93	    if (len > rem) len = (size_t)rem;
94	    if (len == 0) return 0;
95	    size_t n = base->Read(buf, len);
96	    rem -= n;
97	    return n;
98	  }
99	};
100	
101	// Counts bytes and optionally reports progress.
102	struct CountInStream : ISeqInStream {
103	  ISeqInStream *base; UInt64 total = 0;
104	  CountInStream(ISeqInStream *b) : base(b) {}
105	  size_t Read(Byte *buf, size_t len) override {
106	    size_t n = base->Read(buf, len);
107	    total += n;
108	    return n;
109	  }
110	};
111	
112	struct CountOutStream : ISeqOutStream {
113	  ISeqOutStream *base; UInt64 total = 0;
114	  CountOutStream(ISeqOutStream *b) : base(b) {}
115	  void Write(const Byte *buf, size_t len) override {
116	    if (base) base->Write(buf, len);
117	    total += len;
118	  }
119	};
120	
121	// Stops after outSize bytes have been produced; extra data is dropped.
122	struct LimitedOutStream : ISeqOutStream {
123	  ISeqOutStream *base; UInt64 rem;
124	  LimitedOutStream(ISeqOutStream *b, UInt64 n) : base(b), rem(n) {}
125	  void Write(const Byte *buf, size_t len) override {
126	    if (len > rem) len = (size_t)rem;
127	    if (len) { base->Write(buf, len); rem -= len; }
128	  }
129	};
130	
131	// Buffered reader used by the header parsers.
132	struct BufferedIn {
133	  ISeqInStream *base;
134	  ByteBuf buf;
135	  size_t pos = 0, filled = 0;
136	  BufferedIn(ISeqInStream *b, size_t cap = 1 << 16) : base(b), buf(cap) {}
137	  int PeekByte() {
138	    if (pos == filled) {
139	      pos = filled = 0;
140	      filled = base->Read(&buf[0], buf.size());
141	      if (filled == 0) return -1;
142	    }
143	    return buf[pos];
144	  }
145	  int GetByte() { int c = PeekByte(); if (c >= 0) pos++; return c; }
146	};
147	
148	void CopyStream(ISeqInStream &in, ISeqOutStream &out, UInt64 *limit, IProgress *progress);
