4	// UTF-16 <-> UTF-8.  Archive formats store names as UTF-16; on Linux we keep
5	// them as UTF-8 everywhere else.  Unpaired surrogates are mapped through the
6	// WTF-8 style encoding so that a name survives a round trip.
7	
8	std::string Utf16ToUtf8(const UInt16 *src, size_t len) {
9	  std::string out;
10	  out.reserve(len + len / 2);
11	  for (size_t i = 0; i < len; i++) {
12	    UInt32 c = src[i];
13	    if (c >= 0xD800 && c < 0xDC00 && i + 1 < len) {
14	      UInt32 c2 = src[i + 1];
15	      if (c2 >= 0xDC00 && c2 < 0xE000) {
16	        c = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00);
17	        i++;
18	      }
19	    }
20	    if (c < 0x80) {
21	      out += (char)c;
22	    } else if (c < 0x800) {
23	      out += (char)(0xC0 | (c >> 6));
24	      out += (char)(0x80 | (c & 0x3F));
25	    } else if (c < 0x10000) {
26	      out += (char)(0xE0 | (c >> 12));
27	      out += (char)(0x80 | ((c >> 6) & 0x3F));
28	      out += (char)(0x80 | (c & 0x3F));
29	    } else {
30	      out += (char)(0xF0 | (c >> 18));
31	      out += (char)(0x80 | ((c >> 12) & 0x3F));
32	      out += (char)(0x80 | ((c >> 6) & 0x3F));
33	      out += (char)(0x80 | (c & 0x3F));
34	    }
35	  }
36	  return out;
37	}
38	
39	void Utf8ToUtf16(const std::string &src, std::vector<UInt16> &dest) {
40	  dest.clear();
41	  dest.reserve(src.size());
42	  size_t i = 0, n = src.size();
43	  while (i < n) {
44	    Byte b = (Byte)src[i];
45	    UInt32 c;
46	    unsigned extra;
47	    if (b < 0x80)        { c = b;         extra = 0; }
48	    else if (b < 0xC0)   { c = b;         extra = 0; }  // stray continuation
49	    else if (b < 0xE0)   { c = b & 0x1F;  extra = 1; }
50	    else if (b < 0xF0)   { c = b & 0x0F;  extra = 2; }
51	    else if (b < 0xF8)   { c = b & 0x07;  extra = 3; }
52	    else                 { c = b;         extra = 0; }
53	    if (i + extra >= n) extra = 0;
54	    bool bad = false;
55	    for (unsigned k = 1; k <= extra; k++) {
56	      Byte cb = (Byte)src[i + k];
57	      if ((cb & 0xC0) != 0x80) { bad = true; break; }
58	      c = (c << 6) | (cb & 0x3F);
59	    }
60	    if (bad) { c = b; extra = 0; }
61	    i += extra + 1;
62	    if (c >= 0x10000) {
63	      if (c > 0x10FFFF) c = 0xFFFD;
64	      c -= 0x10000;
65	      dest.push_back((UInt16)(0xD800 + (c >> 10)));
66	      dest.push_back((UInt16)(0xDC00 + (c & 0x3FF)));
67	    } else {
68	      dest.push_back((UInt16)c);
69	    }
70	  }
71	}
72	
73	bool StrEqNoCase(const char *a, const char *b) {
74	  for (;; a++, b++) {
75	    int ca = tolower((unsigned char)*a), cb = tolower((unsigned char)*b);
76	    if (ca != cb) return false;
77	    if (ca == 0) return true;
78	  }
79	}
80	
81	bool StrEqNoCase(const std::string &a, const char *b) { return StrEqNoCase(a.c_str(), b); }
82	
83	std::string ToLower(const std::string &s) {
84	  std::string r(s);
85	  for (size_t i = 0; i < r.size(); i++) r[i] = (char)tolower((unsigned char)r[i]);
86	  return r;
87	}
88	
89	std::string ToUpper(const std::string &s) {
90	  std::string r(s);
91	  for (size_t i = 0; i < r.size(); i++) r[i] = (char)toupper((unsigned char)r[i]);
92	  return r;
93	}
