// Concrete hash implementations: CRC-32, CRC-64, SHA-1, SHA-256 and XXH64.
//
// hash.h declares the public registry (CreateHasher etc.).  This header
// additionally exposes the streaming contexts so that other modules - the AES
// key derivation in particular - can hash without going through IHasher.
#pragma once

#include "hash.h"

// ---------------------------------------------------------------------- CRC
//
// Crc32Update()/Crc64Update() work on the raw, un-finalised register value:
// start from kCrc32Init / kCrc64Init and xor the result with the same constant
// once the stream ends.  Crc32Calc()/Crc64Calc() do that for you.
//
// CRC-32 is the IEEE one (reflected, poly 0xEDB88320).
// CRC-64 is the variant 7-Zip uses (reflected, poly 0xC96C5795D7870F42).

const UInt64 kCrc64Init = ~(UInt64)0;

UInt64 Crc64Calc(const void *data, size_t size);

// ------------------------------------------------------------------ SHA-256

struct Sha256Ctx {
  UInt32 state[8];
  UInt64 count;         // total number of bytes fed in
  unsigned bufPos;      // bytes held in buf
  Byte buf[64];

  void Init();
  void Update(const Byte *data, size_t size);
  // Writes 32 bytes as big-endian words.  Call Init() again before reuse.
  void Final(Byte digest[32]);
};

// ------------------------------------------------------------------- SHA-1

struct Sha1Ctx {
  UInt32 state[5];
  UInt64 count;
  unsigned bufPos;
  Byte buf[64];

  void Init();
  void Update(const Byte *data, size_t size);
  // Writes 20 bytes as big-endian words.
  void Final(Byte digest[20]);
};

void Sha1Buf(const void *data, size_t size, Byte digest[20]);

// ------------------------------------------------------------------- XXH64

struct Xxh64Ctx {
  UInt64 acc[4];
  UInt64 total;
  unsigned bufPos;
  Byte buf[32];

  void Init(UInt64 seed = 0);
  void Update(const Byte *data, size_t size);
  // Does not disturb the context, so it may be called repeatedly.
  UInt64 Digest() const;
};

UInt64 Xxh64Calc(const void *data, size_t size, UInt64 seed = 0);

// CRC-32, CRC-64, SHA-1, SHA-256 and XXH64.
#include "hashers.h"

// ============================================================================
// CRC
// ============================================================================
//
// Both CRCs are "reflected": the register is shifted right and the polynomial
// is stored bit-reversed.  The tables below are the classic slicing-by-8
// layout, built at compile time so there is no initialisation order problem.

namespace {

struct Crc32Tab { UInt32 t[8][256]; };
struct Crc64Tab { UInt64 t[8][256]; };

constexpr Crc32Tab MakeCrc32Tab() {
  Crc32Tab r = {};
  for (unsigned i = 0; i < 256; i++) {
    UInt32 c = i;
    for (unsigned k = 0; k < 8; k++)
      c = (c >> 1) ^ (0xEDB88320u & (0u - (c & 1)));
    r.t[0][i] = c;
  }
  for (unsigned s = 1; s < 8; s++)
    for (unsigned i = 0; i < 256; i++) {
      UInt32 c = r.t[s - 1][i];
      r.t[s][i] = (c >> 8) ^ r.t[0][c & 0xFF];
    }
  return r;
}

constexpr Crc64Tab MakeCrc64Tab() {
  Crc64Tab r = {};
  for (unsigned i = 0; i < 256; i++) {
    UInt64 c = i;
    for (unsigned k = 0; k < 8; k++)
      c = (c >> 1) ^ (0xC96C5795D7870F42ull & (0ull - (c & 1)));
    r.t[0][i] = c;
  }
  for (unsigned s = 1; s < 8; s++)
    for (unsigned i = 0; i < 256; i++) {
      UInt64 c = r.t[s - 1][i];
      r.t[s][i] = (c >> 8) ^ r.t[0][c & 0xFF];
    }
  return r;
}

constexpr Crc32Tab g_crc32 = MakeCrc32Tab();
constexpr Crc64Tab g_crc64 = MakeCrc64Tab();

}  // namespace

UInt32 Crc32Update(UInt32 crc, const void *data, size_t size) {
  const Byte *p = (const Byte *)data;
  // Step to an 8 byte boundary first so the main loop can use aligned loads.
  for (; size != 0 && ((size_t)(uintptr_t)p & 7) != 0; size--, p++)
    crc = g_crc32.t[0][(crc ^ *p) & 0xFF] ^ (crc >> 8);
  for (; size >= 8; size -= 8, p += 8) {
    crc ^= GetUi32(p);
    const UInt32 hi = GetUi32(p + 4);
    crc = g_crc32.t[7][crc & 0xFF]
        ^ g_crc32.t[6][(crc >> 8) & 0xFF]
        ^ g_crc32.t[5][(crc >> 16) & 0xFF]
        ^ g_crc32.t[4][crc >> 24]
        ^ g_crc32.t[3][hi & 0xFF]
        ^ g_crc32.t[2][(hi >> 8) & 0xFF]
        ^ g_crc32.t[1][(hi >> 16) & 0xFF]
        ^ g_crc32.t[0][hi >> 24];
  }
  for (; size != 0; size--, p++)
    crc = g_crc32.t[0][(crc ^ *p) & 0xFF] ^ (crc >> 8);
  return crc;
}

UInt32 Crc32Calc(const void *data, size_t size) {
  return Crc32Update(kCrc32Init, data, size) ^ kCrc32Init;
}

UInt64 Crc64Update(UInt64 crc, const void *data, size_t size) {
  const Byte *p = (const Byte *)data;
  for (; size != 0 && ((size_t)(uintptr_t)p & 7) != 0; size--, p++)
    crc = g_crc64.t[0][(crc ^ *p) & 0xFF] ^ (crc >> 8);
  for (; size >= 8; size -= 8, p += 8) {
    crc ^= GetUi64(p);
    crc = g_crc64.t[7][crc & 0xFF]
        ^ g_crc64.t[6][(crc >> 8) & 0xFF]
        ^ g_crc64.t[5][(crc >> 16) & 0xFF]
        ^ g_crc64.t[4][(crc >> 24) & 0xFF]
        ^ g_crc64.t[3][(crc >> 32) & 0xFF]
        ^ g_crc64.t[2][(crc >> 40) & 0xFF]
        ^ g_crc64.t[1][(crc >> 48) & 0xFF]
        ^ g_crc64.t[0][(crc >> 56) & 0xFF];
  }
  for (; size != 0; size--, p++)
    crc = g_crc64.t[0][(crc ^ *p) & 0xFF] ^ (crc >> 8);
  return crc;
}

UInt64 Crc64Calc(const void *data, size_t size) {
  return Crc64Update(kCrc64Init, data, size) ^ kCrc64Init;
}

// ============================================================================
// SHA-256  (FIPS 180-4)
// ============================================================================

namespace {

inline UInt32 Rotr32(UInt32 x, unsigned n) { return (x >> n) | (x << (32 - n)); }
inline UInt32 Rotl32(UInt32 x, unsigned n) { return (x << n) | (x >> (32 - n)); }

const UInt32 kSha256K[64] = {
  0x428A2F98, 0x71374491, 0xB5C0FBCF, 0xE9B5DBA5, 0x3956C25B, 0x59F111F1,
  0x923F82A4, 0xAB1C5ED5, 0xD807AA98, 0x12835B01, 0x243185BE, 0x550C7DC3,
  0x72BE5D74, 0x80DEB1FE, 0x9BDC06A7, 0xC19BF174, 0xE49B69C1, 0xEFBE4786,
  0x0FC19DC6, 0x240CA1CC, 0x2DE92C6F, 0x4A7484AA, 0x5CB0A9DC, 0x76F988DA,
  0x983E5152, 0xA831C66D, 0xB00327C8, 0xBF597FC7, 0xC6E00BF3, 0xD5A79147,
  0x06CA6351, 0x14292967, 0x27B70A85, 0x2E1B2138, 0x4D2C6DFC, 0x53380D13,
  0x650A7354, 0x766A0ABB, 0x81C2C92E, 0x92722C85, 0xA2BFE8A1, 0xA81A664B,
  0xC24B8B70, 0xC76C51A3, 0xD192E819, 0xD6990624, 0xF40E3585, 0x106AA070,
  0x19A4C116, 0x1E376C08, 0x2748774C, 0x34B0BCB5, 0x391C0CB3, 0x4ED8AA4A,
  0x5B9CCA4F, 0x682E6FF3, 0x748F82EE, 0x78A5636F, 0x84C87814, 0x8CC70208,
  0x90BEFFFA, 0xA4506CEB, 0xBEF9A3F7, 0xC67178F2
};

void Sha256Blocks(UInt32 *s, const Byte *p, size_t blocks) {
  for (; blocks != 0; blocks--, p += 64) {
    UInt32 w[64];
    for (unsigned i = 0; i < 16; i++)
      w[i] = GetBe32(p + i * 4);
    for (unsigned i = 16; i < 64; i++) {
      const UInt32 x = w[i - 15], y = w[i - 2];
      const UInt32 s0 = Rotr32(x, 7) ^ Rotr32(x, 18) ^ (x >> 3);
      const UInt32 s1 = Rotr32(y, 17) ^ Rotr32(y, 19) ^ (y >> 10);
      w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    UInt32 a = s[0], b = s[1], c = s[2], d = s[3];
    UInt32 e = s[4], f = s[5], g = s[6], h = s[7];
    for (unsigned i = 0; i < 64; i++) {
      const UInt32 S1 = Rotr32(e, 6) ^ Rotr32(e, 11) ^ Rotr32(e, 25);
      const UInt32 ch = (e & f) ^ (~e & g);
      const UInt32 t1 = h + S1 + ch + kSha256K[i] + w[i];
      const UInt32 S0 = Rotr32(a, 2) ^ Rotr32(a, 13) ^ Rotr32(a, 22);
      const UInt32 maj = (a & b) ^ (a & c) ^ (b & c);
      const UInt32 t2 = S0 + maj;
      h = g; g = f; f = e; e = d + t1;
      d = c; c = b; b = a; a = t1 + t2;
    }
    s[0] += a; s[1] += b; s[2] += c; s[3] += d;
    s[4] += e; s[5] += f; s[6] += g; s[7] += h;
  }
}

}  // namespace

void Sha256Ctx::Init() {
  state[0] = 0x6A09E667; state[1] = 0xBB67AE85;
  state[2] = 0x3C6EF372; state[3] = 0xA54FF53A;
  state[4] = 0x510E527F; state[5] = 0x9B05688C;
  state[6] = 0x1F83D9AB; state[7] = 0x5BE0CD19;
  count = 0;
  bufPos = 0;
}

void Sha256Ctx::Update(const Byte *data, size_t size) {
  count += size;
  if (bufPos != 0) {
    const unsigned need = 64 - bufPos;
    if (size < need) {
      memcpy(buf + bufPos, data, size);
      bufPos += (unsigned)size;
      return;
    }
    memcpy(buf + bufPos, data, need);
    data += need;
    size -= need;
    Sha256Blocks(state, buf, 1);
    bufPos = 0;
  }
  if (size >= 64) {
    const size_t blocks = size >> 6;
    Sha256Blocks(state, data, blocks);
    data += blocks << 6;
    size -= blocks << 6;
  }
  if (size != 0) {
    memcpy(buf, data, size);
    bufPos = (unsigned)size;
  }
}

void Sha256Ctx::Final(Byte digest[32]) {
  const UInt64 bits = count << 3;
  unsigned n = bufPos;
  buf[n++] = 0x80;
  if (n > 56) {
    memset(buf + n, 0, 64 - n);
    Sha256Blocks(state, buf, 1);
    n = 0;
  }
  memset(buf + n, 0, 56 - n);
  SetBe64(buf + 56, bits);
  Sha256Blocks(state, buf, 1);
  bufPos = 0;
  for (unsigned i = 0; i < 8; i++)
    SetBe32(digest + i * 4, state[i]);
}

void Sha256Buf(const void *data, size_t size, Byte digest[32]) {
  Sha256Ctx ctx;
  ctx.Init();
  ctx.Update((const Byte *)data, size);
  ctx.Final(digest);
}

// ============================================================================
// SHA-1  (FIPS 180-4)
// ============================================================================

namespace {

void Sha1Blocks(UInt32 *s, const Byte *p, size_t blocks) {
  for (; blocks != 0; blocks--, p += 64) {
    UInt32 w[80];
    for (unsigned i = 0; i < 16; i++)
      w[i] = GetBe32(p + i * 4);
    for (unsigned i = 16; i < 80; i++)
      w[i] = Rotl32(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    UInt32 a = s[0], b = s[1], c = s[2], d = s[3], e = s[4];
    for (unsigned i = 0; i < 80; i++) {
      UInt32 f, k;
      if (i < 20)      { f = (b & c) | (~b & d);          k = 0x5A827999; }
      else if (i < 40) { f = b ^ c ^ d;                   k = 0x6ED9EBA1; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
      else             { f = b ^ c ^ d;                   k = 0xCA62C1D6; }
      const UInt32 t = Rotl32(a, 5) + f + e + k + w[i];
      e = d; d = c; c = Rotl32(b, 30); b = a; a = t;
    }
    s[0] += a; s[1] += b; s[2] += c; s[3] += d; s[4] += e;
  }
}

}  // namespace

void Sha1Ctx::Init() {
  state[0] = 0x67452301; state[1] = 0xEFCDAB89; state[2] = 0x98BADCFE;
  state[3] = 0x10325476; state[4] = 0xC3D2E1F0;
  count = 0;
  bufPos = 0;
}

void Sha1Ctx::Update(const Byte *data, size_t size) {
  count += size;
  if (bufPos != 0) {
    const unsigned need = 64 - bufPos;
    if (size < need) {
      memcpy(buf + bufPos, data, size);
      bufPos += (unsigned)size;
      return;
    }
    memcpy(buf + bufPos, data, need);
    data += need;
    size -= need;
    Sha1Blocks(state, buf, 1);
    bufPos = 0;
  }
  if (size >= 64) {
    const size_t blocks = size >> 6;
    Sha1Blocks(state, data, blocks);
    data += blocks << 6;
    size -= blocks << 6;
  }
  if (size != 0) {
    memcpy(buf, data, size);
    bufPos = (unsigned)size;
  }
}

void Sha1Ctx::Final(Byte digest[20]) {
  const UInt64 bits = count << 3;
  unsigned n = bufPos;
  buf[n++] = 0x80;
  if (n > 56) {
    memset(buf + n, 0, 64 - n);
    Sha1Blocks(state, buf, 1);
    n = 0;
  }
  memset(buf + n, 0, 56 - n);
  SetBe64(buf + 56, bits);
  Sha1Blocks(state, buf, 1);
  bufPos = 0;
  for (unsigned i = 0; i < 5; i++)
    SetBe32(digest + i * 4, state[i]);
}

void Sha1Buf(const void *data, size_t size, Byte digest[20]) {
  Sha1Ctx ctx;
  ctx.Init();
  ctx.Update((const Byte *)data, size);
  ctx.Final(digest);
}

// ============================================================================
// XXH64  (seed 0 is what 7-Zip uses)
// ============================================================================

namespace {

const UInt64 kXxhP1 = 0x9E3779B185EBCA87ull;
const UInt64 kXxhP2 = 0xC2B2AE3D27D4EB4Full;
const UInt64 kXxhP3 = 0x165667B19E3779F9ull;
const UInt64 kXxhP4 = 0x85EBCA77C2B2AE63ull;
const UInt64 kXxhP5 = 0x27D4EB2F165667C5ull;

inline UInt64 Rotl64(UInt64 x, unsigned n) { return (x << n) | (x >> (64 - n)); }

inline UInt64 XxhRound(UInt64 acc, UInt64 input) {
  acc += input * kXxhP2;
  acc = Rotl64(acc, 31);
  return acc * kXxhP1;
}

inline UInt64 XxhMerge(UInt64 acc, UInt64 val) {
  acc ^= XxhRound(0, val);
  return acc * kXxhP1 + kXxhP4;
}

}  // namespace

void Xxh64Ctx::Init(UInt64 seed) {
  acc[0] = seed + kXxhP1 + kXxhP2;
  acc[1] = seed + kXxhP2;
  acc[2] = seed;
  acc[3] = seed - kXxhP1;
  total = 0;
  bufPos = 0;
}

void Xxh64Ctx::Update(const Byte *data, size_t size) {
  total += size;
  if (bufPos != 0) {
    const unsigned need = 32 - bufPos;
    if (size < need) {
      memcpy(buf + bufPos, data, size);
      bufPos += (unsigned)size;
      return;
    }
    memcpy(buf + bufPos, data, need);
    data += need;
    size -= need;
    for (unsigned i = 0; i < 4; i++)
      acc[i] = XxhRound(acc[i], GetUi64(buf + i * 8));
    bufPos = 0;
  }
  for (; size >= 32; size -= 32, data += 32)
    for (unsigned i = 0; i < 4; i++)
      acc[i] = XxhRound(acc[i], GetUi64(data + i * 8));
  if (size != 0) {
    memcpy(buf, data, size);
    bufPos = (unsigned)size;
  }
}

UInt64 Xxh64Ctx::Digest() const {
  UInt64 h;
  if (total >= 32) {
    h = Rotl64(acc[0], 1) + Rotl64(acc[1], 7) + Rotl64(acc[2], 12) + Rotl64(acc[3], 18);
    h = XxhMerge(h, acc[0]);
    h = XxhMerge(h, acc[1]);
    h = XxhMerge(h, acc[2]);
    h = XxhMerge(h, acc[3]);
  } else {
    // acc[2] still holds the seed.
    h = acc[2] + kXxhP5;
  }
  h += total;

  const Byte *p = buf;
  unsigned n = bufPos;
  for (; n >= 8; n -= 8, p += 8) {
    h ^= XxhRound(0, GetUi64(p));
    h = Rotl64(h, 27) * kXxhP1 + kXxhP4;
  }
  if (n >= 4) {
    h ^= (UInt64)GetUi32(p) * kXxhP1;
    h = Rotl64(h, 23) * kXxhP2 + kXxhP3;
    n -= 4;
    p += 4;
  }
  for (; n != 0; n--, p++) {
    h ^= (UInt64)*p * kXxhP5;
    h = Rotl64(h, 11) * kXxhP1;
  }

  h ^= h >> 33;
  h *= kXxhP2;
  h ^= h >> 29;
  h *= kXxhP3;
  h ^= h >> 32;
  return h;
}

UInt64 Xxh64Calc(const void *data, size_t size, UInt64 seed) {
  Xxh64Ctx ctx;
  ctx.Init(seed);
  ctx.Update((const Byte *)data, size);
  return ctx.Digest();
}

// ============================================================================
// IHasher wrappers
// ============================================================================
//
// 7-Zip prints every one of these digests as a plain big-endian hex number of
// DigestSize() bytes, so Final() always emits big-endian.

namespace {

struct Crc32Hasher : IHasher {
  UInt32 v;
  Crc32Hasher() { Init(); }
  void Init() override { v = kCrc32Init; }
  void Update(const Byte *data, size_t size) override { v = Crc32Update(v, data, size); }
  void Final(Byte *digest) override { SetBe32(digest, v ^ kCrc32Init); }
  unsigned DigestSize() const override { return 4; }
};

struct Crc64Hasher : IHasher {
  UInt64 v;
  Crc64Hasher() { Init(); }
  void Init() override { v = kCrc64Init; }
  void Update(const Byte *data, size_t size) override { v = Crc64Update(v, data, size); }
  void Final(Byte *digest) override { SetBe64(digest, v ^ kCrc64Init); }
  unsigned DigestSize() const override { return 8; }
};

struct Sha1Hasher : IHasher {
  Sha1Ctx ctx;
  Sha1Hasher() { Init(); }
  void Init() override { ctx.Init(); }
  void Update(const Byte *data, size_t size) override { ctx.Update(data, size); }
  void Final(Byte *digest) override { ctx.Final(digest); }
  unsigned DigestSize() const override { return 20; }
};

struct Sha256Hasher : IHasher {
  Sha256Ctx ctx;
  Sha256Hasher() { Init(); }
  void Init() override { ctx.Init(); }
  void Update(const Byte *data, size_t size) override { ctx.Update(data, size); }
  void Final(Byte *digest) override { ctx.Final(digest); }
  unsigned DigestSize() const override { return 32; }
};

struct Xxh64Hasher : IHasher {
  Xxh64Ctx ctx;
  Xxh64Hasher() { Init(); }
  void Init() override { ctx.Init(0); }
  void Update(const Byte *data, size_t size) override { ctx.Update(data, size); }
  void Final(Byte *digest) override { SetBe64(digest, ctx.Digest()); }
  unsigned DigestSize() const override { return 8; }
};

}  // namespace

IHasher *CreateHasher(UInt64 id) {
  switch (id) {
    case HashID::kCRC32:  return new Crc32Hasher();
    case HashID::kCRC64:  return new Crc64Hasher();
    case HashID::kSHA1:   return new Sha1Hasher();
    case HashID::kSHA256: return new Sha256Hasher();
    case HashID::kXXH64:  return new Xxh64Hasher();
    default: return nullptr;
  }
}

IHasher *CreateHasherByName(const char *name) {
  if (!name) return nullptr;
  if (StrEqNoCase(name, "crc32"))  return new Crc32Hasher();
  if (StrEqNoCase(name, "crc64"))  return new Crc64Hasher();
  if (StrEqNoCase(name, "sha1"))   return new Sha1Hasher();
  if (StrEqNoCase(name, "sha256")) return new Sha256Hasher();
  if (StrEqNoCase(name, "xxh64"))  return new Xxh64Hasher();
  return nullptr;
}

// Test harness for /workspace/src/hashers.cpp -- lives outside the source tree.
#include "hashers.h"
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <string>
#include <vector>
#include <ctime>

static std::string Hex(const Byte *p, unsigned n, bool upper) {
  static const char *lo = "0123456789abcdef";
  static const char *up = "0123456789ABCDEF";
  const char *d = upper ? up : lo;
  std::string s;
  for (unsigned i = 0; i < n; i++) { s += d[p[i] >> 4]; s += d[p[i] & 15]; }
  return s;
}

static std::string HashOf(const char *name, const Byte *data, size_t size, bool upper) {
  IHasher *h = CreateHasherByName(name);
  if (!h) { printf("!! no hasher %s\n", name); exit(1); }
  h->Init();
  h->Update(data, size);
  Byte dig[64];
  h->Final(dig);
  std::string r = Hex(dig, h->DigestSize(), upper);
  delete h;
  return r;
}

// Same digest, but fed through pseudo-random chunk splits.
static std::string HashChunked(const char *name, const Byte *data, size_t size,
                               bool upper, unsigned seed) {
  IHasher *h = CreateHasherByName(name);
  h->Init();
  UInt64 st = seed * 6364136223846793005ull + 1442695040888963407ull;
  size_t pos = 0;
  while (pos < size) {
    st = st * 6364136223846793005ull + 1442695040888963407ull;
    size_t n = (size_t)((st >> 33) % 97);      // 0..96, exercises 0-length calls
    if (n > size - pos) n = size - pos;
    h->Update(data + pos, n);
    pos += n;
  }
  Byte dig[64];
  h->Final(dig);
  std::string r = Hex(dig, h->DigestSize(), upper);
  delete h;
  return r;
}

static bool g_fail = false;

static void Check(const std::string &got, const std::string &want, const char *what) {
  if (got != want) {
    printf("FAIL %-28s got %s want %s\n", what, got.c_str(), want.c_str());
    g_fail = true;
  }
}

static void PrintAll(const Byte *d, size_t n) {
  printf("%s %s %s %s %s\n",
         HashOf("crc32", d, n, true).c_str(),
         HashOf("crc64", d, n, true).c_str(),
         HashOf("sha256", d, n, false).c_str(),
         HashOf("sha1", d, n, false).c_str(),
         HashOf("xxh64", d, n, true).c_str());
}

static void GenRandom(std::vector<Byte> &v, size_t n, UInt64 seed) {
  v.resize(n);
  UInt64 s = seed | 1;
  for (size_t i = 0; i < n; i++) {
    s ^= s << 13; s ^= s >> 7; s ^= s << 17;
    v[i] = (Byte)(s >> 24);
  }
}

int main(int argc, char **argv) {
  if (argc >= 3 && strcmp(argv[1], "file") == 0) {
    FILE *f = fopen(argv[2], "rb");
    if (!f) { perror("open"); return 1; }
    std::vector<Byte> v;
    Byte tmp[65536];
    size_t n;
    while ((n = fread(tmp, 1, sizeof(tmp), f)) > 0) v.insert(v.end(), tmp, tmp + n);
    fclose(f);
    PrintAll(v.empty() ? nullptr : &v[0], v.size());
    return 0;
  }

  if (argc >= 3 && strcmp(argv[1], "bench") == 0) {
    size_t mb = (size_t)atoi(argv[2]);
    std::vector<Byte> v;
    GenRandom(v, mb << 20, 12345);
    const char *names[] = { "crc32", "crc64", "sha1", "sha256", "xxh64" };
    for (int i = 0; i < 5; i++) {
      clock_t t0 = clock();
      IHasher *h = CreateHasherByName(names[i]);
      h->Init();
      h->Update(&v[0], v.size());
      Byte dig[64];
      h->Final(dig);
      double sec = (double)(clock() - t0) / CLOCKS_PER_SEC;
      printf("%-7s %6.2f MB/s  %s\n", names[i], (double)mb / (sec > 0 ? sec : 1e-9),
             Hex(dig, h->DigestSize(), true).c_str());
      delete h;
    }
    return 0;
  }

  // ------------------------------------------------------------ known vectors
  {
    const char *s = "hello world\n";
    const Byte *d = (const Byte *)s;
    size_t n = 12;
    Check(HashOf("crc32", d, n, true), "AF083B2D", "hello crc32");
    Check(HashOf("crc64", d, n, true), "CFBF7F6AC4FFF2A1", "hello crc64");
    Check(HashOf("sha256", d, n, false),
          "a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447", "hello sha256");
    Check(HashOf("sha1", d, n, false),
          "22596363b3de40b06f981fb85d82312e8c0ed511", "hello sha1");
    Check(HashOf("xxh64", d, n, true), "5215E13B207D6D8C", "hello xxh64");
  }
  {
    // Empty input.
    Check(HashOf("crc32", nullptr, 0, true), "00000000", "empty crc32");
    Check(HashOf("crc64", nullptr, 0, true), "0000000000000000", "empty crc64");
    Check(HashOf("sha256", nullptr, 0, false),
          "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "empty sha256");
    Check(HashOf("sha1", nullptr, 0, false),
          "da39a3ee5e6b4b0d3255bfef95601890afd80709", "empty sha1");
    Check(HashOf("xxh64", nullptr, 0, true), "EF46DB3751D8E999", "empty xxh64");
  }
  {
    const Byte *d = (const Byte *)"abc";
    Check(HashOf("crc32", d, 3, true), "352441C2", "abc crc32");
    Check(HashOf("sha256", d, 3, false),
          "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", "abc sha256");
    Check(HashOf("sha1", d, 3, false),
          "a9993e364706816aba3e25717850c26c9cd0d89d", "abc sha1");
    Check(HashOf("xxh64", d, 3, true), "44BC2CF5AD770999", "abc xxh64");
  }
  {
    // 1,000,000 x 'a'
    std::vector<Byte> v(1000000, 'a');
    Check(HashOf("sha256", &v[0], v.size(), false),
          "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0", "1Ma sha256");
    Check(HashOf("sha1", &v[0], v.size(), false),
          "34aa973cd4c4daa4f61eeb2bdbad27316534016f", "1Ma sha1");
    Check(HashOf("crc32", &v[0], v.size(), true), "DC25BFBC", "1Ma crc32");
  }
  {
    // "The quick brown fox jumps over the lazy dog"
    const char *s = "The quick brown fox jumps over the lazy dog";
    const Byte *d = (const Byte *)s;
    size_t n = strlen(s);
    Check(HashOf("sha1", d, n, false), "2fd4e1c67a2d28fced849ee1bb76e7391b93eb12", "fox sha1");
    Check(HashOf("crc32", d, n, true), "414FA339", "fox crc32");
    Check(HashOf("xxh64", d, n, true), "0B242D361FDA71BC", "fox xxh64");
  }

  // -------------------------------------------------- id-based factory parity
  {
    struct { UInt64 id; const char *name; unsigned ds; } tab[] = {
      { HashID::kCRC32, "crc32", 4 }, { HashID::kCRC64, "crc64", 8 },
      { HashID::kSHA1, "sha1", 20 }, { HashID::kSHA256, "sha256", 32 },
      { HashID::kXXH64, "xxh64", 8 },
    };
    std::vector<Byte> v;
    GenRandom(v, 4096, 7);
    for (auto &e : tab) {
      IHasher *h = CreateHasher(e.id);
      if (!h) { printf("FAIL CreateHasher(%llx)\n", (unsigned long long)e.id); g_fail = true; continue; }
      if (h->DigestSize() != e.ds) { printf("FAIL digest size %s\n", e.name); g_fail = true; }
      h->Init();
      h->Update(&v[0], v.size());
      Byte dig[64];
      h->Final(dig);
      Check(Hex(dig, h->DigestSize(), true), HashOf(e.name, &v[0], v.size(), true), e.name);
      delete h;
    }
    if (CreateHasher(0x999) != nullptr) { printf("FAIL unknown id\n"); g_fail = true; }
    if (CreateHasherByName("md5") != nullptr) { printf("FAIL unknown name\n"); g_fail = true; }
    IHasher *u = CreateHasherByName("SHA256");   // case insensitive
    if (!u) { printf("FAIL case-insensitive name\n"); g_fail = true; } else delete u;
  }

  // -------------------------------------------------------- reuse after Init()
  {
    std::vector<Byte> a, b;
    GenRandom(a, 1000, 1);
    GenRandom(b, 20000, 2);
    const char *names[] = { "crc32", "crc64", "sha1", "sha256", "xxh64" };
    for (int i = 0; i < 5; i++) {
      IHasher *h = CreateHasherByName(names[i]);
      h->Init(); h->Update(&a[0], a.size());
      Byte d1[64]; h->Final(d1);
      h->Init(); h->Update(&b[0], b.size());
      Byte d2[64]; h->Final(d2);
      Check(Hex(d2, h->DigestSize(), true), HashOf(names[i], &b[0], b.size(), true),
            (std::string("reuse ") + names[i]).c_str());
      delete h;
    }
  }

  // --------------------------------------------------- chunk-split invariance
  {
    const size_t sizes[] = { 0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 32, 33,
                             63, 64, 65, 100, 127, 128, 129, 255, 256,
                             65535, 65536, 65537, 1 << 20, 5 << 20 };
    const char *names[] = { "crc32", "crc64", "sha1", "sha256", "xxh64" };
    std::vector<Byte> v;
    for (size_t si = 0; si < sizeof(sizes) / sizeof(sizes[0]); si++) {
      size_t n = sizes[si];
      for (int kind = 0; kind < 3; kind++) {
        if (kind == 0) { v.assign(n, 0); }                            // zeros
        else if (kind == 1) { GenRandom(v, n, n * 2654435761u + 1); }  // random
        else {                                                        // text-ish
          v.resize(n);
          for (size_t i = 0; i < n; i++) v[i] = (Byte)(" the quick brown fox\n"[i % 21]);
        }
        const Byte *p = v.empty() ? nullptr : &v[0];
        for (int i = 0; i < 5; i++) {
          std::string one = HashOf(names[i], p, n, true);
          for (unsigned seed = 1; seed <= 3; seed++) {
            char what[96];
            snprintf(what, sizeof(what), "split %s n=%zu kind=%d s=%u", names[i], n, kind, seed);
            Check(HashChunked(names[i], p, n, true, seed), one, what);
          }
        }
      }
    }
  }

  // ------------------------------------------- unaligned start offsets for CRC
  {
    std::vector<Byte> v;
    GenRandom(v, 4096, 99);
    for (unsigned off = 0; off < 16; off++)
      for (unsigned len = 0; len < 40; len++) {
        // Compare the table-driven path against a bit-by-bit reference.
        UInt32 c = kCrc32Init;
        UInt64 c64 = kCrc64Init;
        for (unsigned i = 0; i < len; i++) {
          c ^= v[off + i];
          for (int k = 0; k < 8; k++) c = (c >> 1) ^ (0xEDB88320u & (0u - (c & 1)));
          c64 ^= v[off + i];
          for (int k = 0; k < 8; k++) c64 = (c64 >> 1) ^ (0xC96C5795D7870F42ull & (0ull - (c64 & 1)));
        }
        char what[64];
        snprintf(what, sizeof(what), "bitwise crc32 off=%u len=%u", off, len);
        Byte want[8];
        SetBe32(want, c ^ kCrc32Init);
        Check(HashOf("crc32", &v[off], len, true), Hex(want, 4, true), what);
        snprintf(what, sizeof(what), "bitwise crc64 off=%u len=%u", off, len);
        SetBe64(want, c64 ^ kCrc64Init);
        Check(HashOf("crc64", &v[off], len, true), Hex(want, 8, true), what);
      }
  }

  // ----------------------------------------------- free-function entry points
  {
    std::vector<Byte> v;
    GenRandom(v, 100000, 4242);
    Byte want[32], got[32];
    Sha256Buf(&v[0], v.size(), want);
    Check(Hex(want, 32, false), HashOf("sha256", &v[0], v.size(), false), "Sha256Buf");
    Sha256Ctx c;
    c.Init();
    for (size_t i = 0; i < v.size(); i += 7)
      c.Update(&v[i], v.size() - i < 7 ? v.size() - i : 7);
    c.Final(got);
    Check(Hex(got, 32, false), Hex(want, 32, false), "Sha256Ctx streaming");

    Byte e[32];
    Sha256Buf(nullptr, 0, e);
    Check(Hex(e, 32, false),
          "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "Sha256Buf empty");

    Byte s1[20];
    Sha1Buf(&v[0], v.size(), s1);
    Check(Hex(s1, 20, false), HashOf("sha1", &v[0], v.size(), false), "Sha1Buf");

    Byte tmp[8];
    SetBe32(tmp, Crc32Calc(&v[0], v.size()));
    Check(Hex(tmp, 4, true), HashOf("crc32", &v[0], v.size(), true), "Crc32Calc");
    SetBe64(tmp, Crc64Calc(&v[0], v.size()));
    Check(Hex(tmp, 8, true), HashOf("crc64", &v[0], v.size(), true), "Crc64Calc");
    SetBe64(tmp, Xxh64Calc(&v[0], v.size()));
    Check(Hex(tmp, 8, true), HashOf("xxh64", &v[0], v.size(), true), "Xxh64Calc");

    // Crc32Update composition over a split.
    UInt32 part = Crc32Update(kCrc32Init, &v[0], 12345);
    part = Crc32Update(part, &v[12345], v.size() - 12345);
    if ((part ^ kCrc32Init) != Crc32Calc(&v[0], v.size())) {
      printf("FAIL Crc32Update composition\n"); g_fail = true;
    }
    UInt64 p64 = Crc64Update(kCrc64Init, &v[0], 12345);
    p64 = Crc64Update(p64, &v[12345], v.size() - 12345);
    if ((p64 ^ kCrc64Init) != Crc64Calc(&v[0], v.size())) {
      printf("FAIL Crc64Update composition\n"); g_fail = true;
    }
  }

  printf(g_fail ? "SELFTEST FAILED\n" : "SELFTEST OK\n");
  return g_fail ? 1 : 0;
}

